actueel as (
select sectie, sch, obj, md5(definitie) as vingerafdruk
from (
  -- ── Functies: de volledige definitie, inclusief body, volatility en search_path
  select 'FUNC'::text as sectie,
         n.nspname::text as sch,
         (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')')::text as obj,
         pg_get_functiondef(p.oid)::text as definitie
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public','storage')
     and not exists (select 1 from pg_depend d
                      where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')

  union all
  -- ── Relaties: de kolomvorm. Naam, type, not-null en default, op volgorde.
  select 'REL', n.nspname::text, c.relname::text,
         coalesce(string_agg(a.attname || ' ' || format_type(a.atttypid, a.atttypmod)
                             || case when a.attnotnull then ' NN' else '' end
                             || coalesce(' D=' || pg_get_expr(ad.adbin, ad.adrelid), ''),
                             E'\n' order by a.attnum), '')
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    left join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
    left join pg_attrdef ad on ad.adrelid = c.oid and ad.adnum = a.attnum
   where n.nspname in ('public','storage') and c.relkind in ('r','p','v','m','f')
     and not exists (select 1 from pg_depend d
                      where d.classid = 'pg_class'::regclass and d.objid = c.oid and d.deptype = 'e')
   group by n.nspname, c.relname

  union all
  -- ── Views/matviews: óók de querytekst; een view kan dezelfde kolommen
  --    houden terwijl de definitie eronder verandert.
  select 'VIEWDEF', n.nspname::text, c.relname::text, pg_get_viewdef(c.oid)::text
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public','storage') and c.relkind in ('v','m')

  union all
  -- ── RLS-policies: predicaat, check, commando en rollen.
  select 'POL', pol.schemaname::text, (pol.tablename || '.' || pol.policyname)::text,
         coalesce(pol.cmd,'') || '|' || coalesce(pol.qual,'') || '|' ||
         coalesce(pol.with_check,'') || '|' || coalesce(array_to_string(pol.roles, ','),'')
    from pg_policies pol
   where pol.schemaname in ('public','storage')

  union all
  -- ── RLS aan/uit per tabel: een policy zegt niets als RLS uit staat.
  select 'RLS', n.nspname::text, c.relname::text,
         (case when c.relrowsecurity then 'aan' else 'uit' end) || '/' ||
         (case when c.relforcerowsecurity then 'force' else 'geen-force' end)
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public','storage') and c.relkind in ('r','p')

  union all
  -- ── Triggers: append-only-sloten en capture-triggers zijn hier de kern.
  select 'TRG', n.nspname::text, (c.relname || '.' || t.tgname)::text,
         pg_get_triggerdef(t.oid)::text
    from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public','storage') and not t.tgisinternal

  union all
  -- ── Indexen: unieke indexen dragen invarianten (idempotentie, quota).
  select 'IDX', n.nspname::text, i.relname::text, pg_get_indexdef(i.oid)::text
    from pg_index x
    join pg_class i on i.oid = x.indexrelid
    join pg_class c on c.oid = x.indrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public','storage') and c.relkind in ('r','p')

  union all
  -- ── Constraints: CHECK-invarianten staan zelden in de allowlist maar
  --    dragen wel de helft van de fail-closed regels.
  select 'CON', n.nspname::text, (c.relname || '.' || con.conname)::text,
         pg_get_constraintdef(con.oid)::text
    from pg_constraint con
    join pg_class c on c.oid = con.conrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public','storage') and c.relkind in ('r','p')
) t
order by sectie, sch, obj
),
vergelijk as (
  select coalesce(v.sch, a.sch) as sch, coalesce(v.obj, a.obj) as obj,
         case when a.obj is null then 'ontbreekt'
              when v.obj is null then 'onbekend'
              when v.vingerafdruk is distinct from a.vingerafdruk then 'afwijkend'
              else 'gelijk' end as oordeel
    from verwacht v
    full outer join actueel a
      on a.sectie = v.sectie and a.sch = v.sch and a.obj = v.obj
)
select '3. SAMENVATTING' as rapport,
       case when sch = 'storage' then 'platform (storage)' else 'applicatie (public)' end as laag,
       oordeel, count(*) as objecten
  from vergelijk group by 2, oordeel order by 2, 3;

-- ── 4. Afwezigheidscontrole: wat verwijderd HOORT te zijn ───────────────────
--  Een contractmigratie laat geen nieuw object achter; zij is uitsluitend te
--  meten aan de afwezigheid van wat zij dropt. Staat het er nog, dan is die
--  migratie niet (volledig) toegepast.
with verwacht_afwezig(soort, object, migratie) as (
  values
    ('FUNC','login_private.open_breakglass_venster(uuid, integer, text)','2026_09_07_microsoft_login_beleidsmodus.sql'),
    ('FUNC','login_private.wachtwoordlogin_toegestaan(uuid, boolean)','2026_09_07_microsoft_login_beleidsmodus.sql'),
    ('FUNC','microsoft_private.bewaar_koppeling(uuid, uuid, text, text, text, text, text, text[], integer, text, text, text)','2026_09_21_423b_t4d_copilot_rollout_contract.sql'),
    ('FUNC','public.aqlab_log_download(uuid)','2026_08_23_h04_herkomst_auditspoor.sql'),
    ('FUNC','public.fn_decision_readiness_check(uuid, text)','2026_08_28_p3d_01_readiness_drop.sql'),
    ('FUNC','public.fn_decision_readiness_overview(uuid)','2026_08_28_p3d_01_readiness_drop.sql'),
    ('FUNC','public.fn_procedure_heropenen(uuid, text)','2026_08_31_p5d_procedure_beeindigen_bediening.sql'),
    ('FUNC','public.fn_stap_open_per_zwaarte(uuid)','2026_08_28_p3d_04_open_per_decision.sql')
)
select '4. AFWEZIGHEIDSCONTROLE' as rapport,
       migratie, soort, object,
       case when soort = 'FUNC' and to_regprocedure(object) is not null then 'NOG AANWEZIG'
            when soort = 'REL'  and to_regclass(object)     is not null then 'NOG AANWEZIG'
            else 'correct afwezig' end as oordeel
  from verwacht_afwezig
 order by 5 desc, 2, 4;
